mapper.select:
SELECT r.id, r.reservation_code, r.room_id, r.user_id, r.subject, r.attendee_count, r.remark, r.start_time, r.end_time, r.status, r.create_time, mr.name AS room_name FROM meeting_room_reservation r LEFT JOIN meeting_room mr ON mr.id = r.room_id AND mr.deleted = 0 WHERE r.deleted = 0
AND r.room_id = #{query.roomId}
AND r.user_id = #{query.userId}
ORDER BY r.create_time DESC
